import React, { useState, useEffect } from 'react';

export const CreateObjectView = observer(({ model }) => {
  const [selectedAsset, setSelectedAsset] = useState(null);

  useEffect(() => {
    model.cleanupScene();
  }, []);

  const handleAssetClick = (asset) => {
    setSelectedAsset(asset);
    model.createObject(asset).then(() => {
      model.setSelectedAsset(asset);
    });
  };

  return (
    <div id="CreateObjectView">
      <h2 id="CreateObjectTitle">Create Object</h2>
      <button id="CleanupSceneButton" onClick={model.cleanupScene}>Cleanup Scene</button>
      <ul id="AvailableAssetsList">
        {model.availableAssets.map((asset) => (
          <li key={asset} id={`AssetItem-${asset}`} onClick={() => handleAssetClick(asset)}>{asset}</li>
        ))}
      </ul>
    </div>
  );
});
```

