```verilog
module ldpc_encoder(
    input wire clk,
    input wire reset,
    input wire data_in[],
    output wire data_out[]
);

reg [7:0] state_reg;
reg [7:0] next_state_reg;
reg [7:0] output_reg;

always @(posedge clk or posedge reset)
begin
    if (reset)
    begin
        state_reg <= 8'b00000000;
        next_state_reg <= 8'b00000000;
        output_reg <= 8'b00000000;
    end else
    begin
        state_reg <= next_state_reg;
        next_state_reg <= state_reg ^ (data_in[7:0] ^ state_reg);
        output_reg <= state_reg;
    end
end

assign data_out[7:0] = output_reg;

endmodule
```

