module ldpc_encoder(
    input wire clk,
    input wire reset,
    input wire data_in[],
    output wire data_out[]
);

reg [7:0] state_reg;
reg [7:0] coefficient_reg[8];

always @(posedge clk or posedge reset)
begin
    if (reset)
