function reverseAdjectiveOrder(sentence) {
  // Split the sentence into words
  const words = sentence.split(" ");

  // Filter out the adjectives (words that end with "-ly" or contain a hyphen)
  const adjectives = words.filter(word => word.endsWith("-ly") || word.includes("-"));

  // Reverse the order of the adjectives
  const reversedAdjectives = adjectives.reverse();

  // Join the words back into a sentence with the reversed adjectives
  const reversedSentence = reversedAdjectives.join(" ") + " " + words.filter(word => !word.endsWith("-ly") && !word.includes("-")).join(" ");

  return reversedSentence;
}

