func processUserData(userData: UserData) -> [String] {
    var categories: [String] = []

    // Extract categories from user clicks
    for click in userData.clicks {
        if let category = click.components(separatedBy: "-").first {
            categories.append(category)
        }
    }

    // Extract colors from user color preferences
    for preference in userData.colorPreferences {
        if let color = preference.components(separatedBy: "-").first {
            categories.append(color)
        }
    }

    // Extract products from user product reviews
    for review in userData.productReviews {
        if let product = review.components(separatedBy: "-").first {
            categories.append(product)
        }
    }

    return categories
}

