Then, create or update your `middleware.js` file in the root directory of your Next.js project to include the `cors` middleware:

```javascript
// middleware.js
import { createServer } from 'http';
import { parse } from 'url';
import { handleRequest } from './handle-request';
import cors from 'cors';

const server = createServer(async (req, res) => {
  const parsedUrl = parse(req.url);
  const { pathname } = parsedUrl;

  // Apply the CORS middleware to all routes except for the API route
  if (pathname !== '/api/') {
    await cors({
      origin: ['https://your-wordpress-domain.com'],
      optionsSuccessStatus: 200,
    })(req, res, () => {
      handleRequest(req, res);
    });
  } else {
    handleRequest(req, res);
  }
});

export default server;
```

Replace `https://your-wordpress-domain.com` with the actual domain name of your WordPress site. This code sets up the `cors` middleware to allow requests from the specified domain.

