function tense = identify_tense(sentence)
    % Split the sentence into words
    words = strsplit(sentence, ' ');

    % Identify the verb
    verb = '';
    for i = 1:length(words)
        if ismember(words{i}, {'be', 'have', 'do', 'go', 'see', 'eat', 'drink', 'sleep', 'swim', 'run', 'jump', 'ride', 'write', 'read', 'learn', 'know', 'think', 'feel', 'want', 'can', 'could', 'may', 'might', 'must', 'ought', 'shall', 'should', 'will', 'would'})
            verb = words{i};
            break;
        end
    end

