    if verb == 'be' || verb == 'have' || verb == 'do' || verb == 'go' || verb == 'see' || verb == 'eat' || verb == 'drink' || verb == 'sleep' || verb == 'swim' || verb == 'run' || verb == 'jump' || verb == 'ride' || verb == 'write' || verb == 'read' || verb == 'learn' || verb == 'know' || verb == 'think' || verb == 'feel' || verb == 'want' || verb == 'can' || verb == 'could' || verb == 'may' || verb == 'might' || verb == 'must' || verb == 'ought' || verb == 'shall' || verb == 'should' || verb == 'will' || verb == 'would' && ismember(words{end-2}, {'today', 'tomorrow', 'yesterday'})
        tense = 'present conditional';
    else
        tense = 'unknown';
    end
end

