Certainly! Here's a MATLAB code that can identify the tense used in a given sentence:

```matlab
function tense = identify_tense(sentence)
    % Split the sentence into words
    words = strsplit(sentence, ' ');

    % Initialize variables
    present = false;
    past = false;
    future = false;

    % Iterate through the words
    for i = 1:length(words)
        % Check for present tense
        if strcmp(words{i}, 'be') && strcmp(words{i+1}, 'ing')
            present = true;
            break;
        end

        % Check for past tense
        if strcmp(words{i}, 'be') && strcmp(words{i+1}, 'en')
            past = true;
            break;
        end

        % Check for future tense
        if strcmp(words{i}, 'will') || strcmp(words{i}, 'shall')
            future = true;
            break;
        end
    end

    % Determine the tense
    if present
        tense = 'present';
    elseif past
        tense = 'past';
    elseif future
        tense = 'future';
    else
        tense = 'other';
    end
end
```

To use this code, simply call it with your sentence as an input:

