using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;

public abstract class RestServiceWrapper<T>
{
    private readonly HttpClient _httpClient;
    private readonly string _authToken;

    public RestServiceWrapper(string authToken)
    {
        _httpClient = new HttpClient();
        _authToken = authToken;
    }

    protected async Task<T> SendAsync(string url, JObject requestBody)
    {
        var requestMessage = new HttpRequestMessage(HttpMethod.Post, url);
        requestMessage.Content = new StringContent(requestBody.ToString());
        requestMessage.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);

        var response = await _httpClient.SendAsync(requestMessage);
        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadAsAsync<T>();
        }
        else
        {
            throw new Exception($"Failed to send request: {await response.Content.ReadAsStringAsync()}");
        }
    }
}

