      if (status === 'OK') {
        var latitude = results[0].geometry.location.lat();
        var longitude = results[0].geometry.location.lng();

        sheet.getRange(sheet.getLastRow() + 1, 2).setValue(latitude); // Assuming the latitude column is in column B
        sheet.getRange(sheet.getLastRow() + 1, 3).setValue(longitude); // Assuming the longitude column is in column C
      } else {
        console.error('Geocode was not successful for the following reason:', status);
      }
    });
  });
}
```

