  const synonyms = {
    'impressive': 'remarkable',
    'achievement': 'accomplishment'
  };

  const enhancedText = Object.entries(synonyms).reduce((acc, [key, value]) => {
    return acc.replace(new RegExp(key, 'gi'), value);
  }, text);

