chrome.runtime.sendMessage({action: 'getBackgroundImage'}, function(response) {
    if (response.backgroundImage) {
        chrome.tabs.query({active: true, currentWindow: true}, function(tabs) {
            chrome.tabs.executeScript(tabs[0].id, {file: 'display_background_image.js', args: [response.backgroundImage]});
        });
