            if key not in combinations:
                combinations[key] = 0
            combinations[key] += 1
    return combinations

def sort_combinations(combinations):
    sorted_combinations = sorted(combinations.items(), key=lambda x: x[1], reverse=True)
    return sorted_combinations

text = "This is a sample text to analyze."
combinations = count_combinations(text)
sorted_combinations = sort_combinations(combinations)

print("Most frequent vowel and consonant combinations:")
for combination, count in sorted_combinations[:10]:
    print(f"{combination}: {count}")
```
