    static string ExtractSummary(string content)
    {
        string[] lines = content.Split('\n');
        string summary = "";

        foreach (string line in lines)
        {
            if (line.Contains("eighth assessment"))
            {
                summary += "Eighth Assessment by scientists from around the world\n";
            }
            else if (line.Contains("ocean levels"))
            {
                summary += "Rising ocean levels\n";
            }
            else if (line.Contains("global temperatures"))
            {
                summary += "Increasing global temperatures\n";
            }
            else if (line.Contains("species loss"))
            {
                summary += "Loss of species\n";
            }
            else if (line.Contains("human activities"))
            {
                summary += "Human activities as the cause of climate change\n";
            }
            else if (line.Contains("drastic changes"))
            {
                summary += "Drastic changes needed to avoid extreme and unprecedented damage\n";
            }
        }

        return summary;
    }
}
