def check_age(age: int) -> bool:
    """Checks if an age is valid (i.e., greater than or equal to 18)."""
    if age >= 18:
        return True
    else:
        return False

def convert_temperature(temperature: float, unit: str) -> float:
    """Converts a temperature from Celsius to Fahrenheit or vice versa."""
    if unit == "C":
        return temperature * 1.8 + 32
    elif unit == "F":
        return (temperature - 32) / 1.8
    else:
