```matlab
% Define population size and number of generations
population_size = 100;
num_generations = 100;

% Initialize population with random genes
population = randi([0 1], population_size, 1);

% Define fitness function
fitness = @(gene) gene; % In this case, fitness is equal to the gene value

% Define selection function
selection = @(fitness_values) fitness_values / sum(fitness_values);

% Define crossover function
crossover = @(parent1, parent2) [parent1(1:floor(length(parent1) / 2)), parent2(ceil(length(parent1) / 2):end)];

% Define mutation function
mutation = @(gene) mod(gene + randn(size(gene)), 2);

% Evolve population over time
for generation = 1:num_generations
    % Evaluate fitness of individuals
    fitness_values = fitness(population);

    % Select parents for crossover
    parent_indices = selection(fitness_values);

    % Crossover between parents
    offspring = crossover(population(parent_indices), population(parent_indices));

    % Mutate offspring
    mutated_offspring = mutation(offspring);

    % Replace population with offspring
    population = mutated_offspring;
end

% Print final population
disp('Final population:');
disp(population);
```
