@Injectable()
export class MyMiddleware implements CanActivate {
  constructor(private readonly environmentGuard: EnvironmentGuard) {}

  async canActivate(context: any): Promise<boolean> {
    await this.environmentGuard.canActivate(context);
    return true;
  }

  async use(context: any, next: () => Promise<any>) {
    // Your middleware logic here
    await next();
  }
}
```

