To create a simple toast notification using React Context, follow these steps:

1. First, let's create a `ToastContext` and a `ToastProvider` component:

```javascript
import React from 'react';

const ToastContext = React.createContext();

function ToastProvider(props) {
  const [toastMessages, setToastMessages] = React.useState([]);

  function addToastMessage(message) {
    setToastMessages((prevMessages) => [...prevMessages, message]);
  }

  return (
    <ToastContext.Provider value={{ addToastMessage }}>
      {props.children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Next, let's create a `Toast` component that will display the toast notifications:

```javascript
import React from 'react';
import { ToastContext } from './ToastContext';

function Toast() {
  const { addToastMessage } = React.useContext(ToastContext);

  const handleClick = () => {
    addToastMessage('This is a toast notification!');
  };

  return (
    <div>
      <button onClick={handleClick}>Show Toast</button>
      <ul>
        {toastMessages.map((message) => (
          <li key={message}>{message}</li>
        ))}
      </ul>
    </div>
  );
}

export default Toast;
```

