import React, { useState } from 'react';
import { useCombobox } from 'downshift';
import { searchEmails } from './searchEmails';

interface EmailInputProps {
  onSelect: (email: string) => void;
}

const EmailInput: React.FC<EmailInputProps> = ({ onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const { isOpen, selectedItem, getMenuProps, getInputProps, getComboboxProps } = useCombobox({
    items: [],
    onSelect,
  });

  const handleInputChange = (event: React.FormEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' && selectedItem) {
      onSelect(selectedItem);
    }
  };

  const handleClick = () => {
    if (isOpen) {
      setInputValue('');
    } else {
      setInputValue(selectedItem || '');
    }
  };

  return (
    <div {...getComboboxProps()}>
      <input
        {...getInputProps()}
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
        onClick={handleClick}
      />
      {isOpen && (
        <ul {...getMenuProps()}>
          {searchEmails(inputValue).map((email) => (
            <li key={email} {...getMenuItemProps(email)}>
              {email}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default EmailInput;
