```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using Accord.MachineLearning;
using Accord.Math;
using Accord.Text;

namespace TextClassification
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load the dataset
            var dataset = new List<LabeledInstance>
            {
                new LabeledInstance("Sports", "The sports game was exciting"),
                new LabeledInstance("Politics", "The politician made a bold statement"),
                new LabeledInstance("Entertainment", "The movie was a thrilling adventure")
            };

            // Preprocess the data
            var vectorizer = new CountVectorizer();
            var transformedData = vectorizer.Transform(dataset);

            // Train the Naive Bayes classifier
            var classifier = new NaiveBayes();
            classifier.Fit(transformedData);

            // Classify a new sentence
            string sentence = "The sports game was exciting";
            var prediction = classifier.Predict(sentence);

            Console.WriteLine($"Predicted label: {prediction}");
        }
    }

    public class LabeledInstance
    {
        public string Label { get; set; }
        public string Text { get; set; }

        public LabeledInstance(string label, string text)
        {
            Label = label;
            Text = text;
        }
    }
}
```

