      "title": "Select folder or file type",
      "placeholder": "Enter folder or file type"
    },
    {
      "action": "get-contents-of-folder",
      "folder": "{{input}}"
    },
    {
      "action": "filter-files",
      "dateRange": {
        "startDate": "{{system}} - 3 years",
        "endDate": "{{system}}"
      }
    },
    {
      "action": "delete-files",
      "files": "{{filteredFiles}}"
    }
  ]
}
```

Replace `"{{input}}"` with the actual folder or file type you want to delete. The `"{{system}}"` variable represents the current system date.

