Here's a Go function that identifies if a given sentence contains a double negative:

```go
package main

import (
	"fmt"
)

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	doubleNegative := detectDoubleNegative(sentence)
	if doubleNegative {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func detectDoubleNegative(sentence string) bool {
	negativeWords := []string{"not", "no", "none", "nothing", "never"}

	// Split the sentence into words
	words := []string{}
	for _, word := range sentence {
		if word == ' ' {
			continue
		}
		words = append(words, string(word))
	}

	// Check for each negative word
	for _, word := range negativeWords {
		if containsWord(words, word) && containsWord(words, "not") {
			return true
		}
	}

	return false
}

func containsWord(slice []string, word string) bool {
	for _, s := range slice {
		if s == word {
			return true
		}
	}
	return false
}
```

