Here's a PowerShell script that recursively checks folders for SIDs that occur only in the SIDHistory of any user or group in the domain:

```powershell
# Define the function to check a folder for SIDHistory references
function CheckFolderForSIDHistoryReferences ($folderPath) {
    # Get the folder's ACLs
    $acl = (Get-Acl -Path $folderPath).Access | Where-Object {$_.IdentityReference -match '^S-1-5-21-'}

    # Loop through each ACL entry
    foreach ($entry in $acl) {
        # Get the SID from the ACL entry
        $sid = $entry.IdentityReference

        # Check if the SID occurs only in the SIDHistory of any user or group in the domain
        if ((Get-ADUser -Filter "SIDHistory -eq '$sid'" -Properties MemberOf).Count -eq 0) {
            # The SID does not occur in the SIDHistory of any user or group in the domain
            Write-Host "The folder '$folderPath' has an ACL entry with a SID that does not occur in the SIDHistory of any user or group in the domain."
        }
    }
}

# Define the root folder to start the search from
$rootFolder = "C:\YourRootFolder"

# Recursively check each folder in the root folder and its subfolders
function CheckSubFoldersForSIDHistoryReferences ($folderPath) {
    # Get the subfolders in the folder
    $subfolders = Get-ChildItem -Path $folderPath -Directory

    # Loop through each subfolder
    foreach ($subfolder in $subfolders) {
        # Call the CheckFolderForSIDHistoryReferences function on the subfolder
        CheckFolderForSIDHistoryReferences $subfolder.FullName

        # Recursively check the subfolder's subfolders
        CheckSubFoldersForSIDHistoryReferences $subfolder.FullName
    }
}

# Call the CheckSubFoldersForSIDHistoryReferences function on the root folder
CheckSubFoldersForSIDHistoryReferences $rootFolder
